pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a malicious recipient contract that reenters getFirstWithdrawalBonus
        address attacker = address(new Attacker(c));
        // Give attacker some ETH to pay for gas (not needed for the attack but safe)
        vm.deal(attacker, 1 ether);
        // No initial rewards
        // Trigger the call: attacker calls getFirstWithdrawalBonus(attacker)
        // The attacker's fallback will reenter getFirstWithdrawalBonus
        vm.prank(attacker);
        bool ok;
        try c.getFirstWithdrawalBonus(attacker) {
            ok = true;
        } catch {
            ok = false;
        }
        // After the transaction, reward balance for attacker should be 100 in reference (only one bonus)
        // In buggy version, the second call inside fallback adds another 100, so reward is 200
        // We check via a public getter: rewardsForA is private, so we need a workaround.
        // Since rewardsForA is private and no getter, we observe via address(c).balance
        // because withdrawReward sends ETH from contract to recipient. In reference, only 100 wei is sent (the bonus) and then claimedBonus prevents second call, so contract balance is 0.
        // In buggy, the first call sends 100, the reentrant call sends another 100, total 200 sent, so contract balance is -200? No, contract had no ETH. Actually, contract starts with 0 ETH; withdrawReward sends 0 because rewardsForA[attacker] is initially 0, then getFirstWithdrawalBonus adds 100, but withdrawReward sends that 100 – so contract must have ETH to send. We need to fund the contract. Let's fund with 2 ether.
        vm.deal(address(c), 2 ether);
        // Now attacker calls getFirstWithdrawalBonus(attacker) again? No, we need to reset state.
        // Better: use a different approach: observe the claimedBonus mapping which is public.
        // But claimedBonus is public with a getter: c.claimedBonus(address).
        // In reference, claimedBonus[attacker] = true after the call (the outer call sets it after withdrawReward returns, and the inner call's require(!claimedBonus[attacker]) fails, so the second bonus is not added).
        // In buggy, the first call sets claimedBonus[attacker] = true before withdrawReward, so the inner call's require(!claimedBonus[attacker]) fails, so it reverts, and the outer call also reverts? Actually, if the inner call reverts, the outer withdrawReward also reverts? No, the inner call is in fallback, revert propagates up and the whole transaction reverts. But in reference, the inner call reverts (because _nonReentrant lock is set? Actually, _nonReentrant is a modifier, so when attacker re-enters getFirstWithdrawalBonus, it calls withdrawReward again? No, attacker's fallback calls getFirstWithdrawalBonus directly, which calls withdrawReward, which checks _nonReentrant: _locked is true, so it reverts. So both versions revert on reentrancy. But the bug is that the order of setting claimedBonus? Let's reexamine: In reference, claimedBonus is set AFTER withdrawReward, so the reentrant call's require(!claimedBonus[attacker]) will be true (since not set yet), so it passes, then it calls withdrawReward, which reverts due to reentrancy lock. So the whole transaction reverts and no state changes. In buggy, claimedBonus is set BEFORE withdrawReward, so the reentrant call's require(!claimedBonus[attacker]) will FAIL, so it reverts immediately, before calling withdrawReward. So both revert. So the observable difference is not about double claiming. 

        // Actually, the difference is that in reference, the reentrant call's require(!claimedBonus) succeeds but then _nonReentrant reverts; in buggy, the reentrant call's require(!claimedBonus) fails and reverts. In both cases the whole tx reverts. But reference sets claimedBonus after withdrawReward, which never completed, so claimedBonus stays false; buggy sets claimedBonus before withdrawReward, and since the reentrant call reverts, the outer call also reverts? No, the outer call is in the fallback; the revert propagates and the whole transaction reverts, so no state changes. So both end with claimedBonus[attacker] = false and rewardsForA[attacker] = 100? Actually, in reference, the outer call added 100 to rewards, then called withdrawReward, which sent 100 and cleared rewards to 0, then set claimedBonus = true. Since withdrawReward succeeded (no reentrancy yet), the state is: rewards=0, claimedBonus=true. Then the reentrant call in fallback: it adds 100 to rewards, then calls withdrawReward, which reverts due to lock. So the reentrant call's state changes (adding 100) revert. So final state: rewards=0, claimedBonus=true. In buggy: outer call adds 100, sets claimedBonus=true, then calls withdrawReward. withdrawReward sends 100, clears rewards to 0. Then fallback calls getFirstWithdrawalBonus: require(!claimedBonus[attacker]) fails because true, so it reverts immediately, no state changes. So final same: rewards=0, claimedBonus=true. So no divergence?

        // Let's reconsider: The bug is that the statement order is different: reference sets claimedBonus after the call, buggy sets it before. The intended property is that the bonus is only given once. But with reentrancy guard, even if claimedBonus is set after, the reentrancy guard prevents calling withdrawReward twice. But what about a reentrancy that only adds to rewards without calling withdrawReward? In buggy, if the fallback calls getFirstWithdrawalBonus again, require(!claimedBonus) fails because it's already true (set before), so it reverts. In reference, require(!claimedBonus) passes (false), then it adds 100 to rewards, then calls withdrawReward, which reverts due to lock, so the addition of 100 reverts as well. So both prevent double addition. So where is the divergence?

        // The correct divergence: Consider a call to getFirstWithdrawalBonus without reentrancy. The only difference is the order of setting claimedBonus relative to the external call. If withdrawReward fails (e.g., because recipient is a contract that reverts in receive), then in reference, claimedBonus would not be set (since it's after the call that reverted), so the user can try again; in buggy, claimedBonus is set before the call, so even if the call reverts, the user cannot claim again. But the problem statement says the second version differs by exactly one statement: swapped lines. So the bug is that the order is wrong: the state mutation (claimedBonus) should happen after the external call to prevent state inconsistency if the call fails. But the reentrancy guard does not help here because the call is direct.

        // So a concrete scenario: a recipient contract that reverts in receive(). In reference, the call to withdrawReward reverts, so claimedBonus remains false, and the user can try again (but rewards were cleared). In buggy, claimedBonus is set to true before the call, so even though the call reverts, the user is marked as having claimed and cannot retry. The property: after a failed withdrawReward (due to recipient reverting), claimedBonus should be false in reference, true in buggy.

        // Let's implement that:
        address recipient = address(new RevertReceiver());
        // Fund contract with some ETH
        vm.deal(address(c), 1 ether);
        // Add initial reward? Actually getFirstWithdrawalBonus adds 100 and calls withdrawReward
        vm.prank(recipient);
        bool ok;
        try c.getFirstWithdrawalBonus(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        // The call reverts because the recipient's receive() reverts.
        // Now check claimedBonus public getter:
        // In reference: claimedBonus[recipient] should be false (since set after call)
        // In buggy: claimedBonus[recipient] should be true (set before call)
        // Note: rewardsForA[recipient] in both: reference cleared before call, so after revert? Actually rewardsForA[recipient] was set to 0 before the call in withdrawReward, and that is already executed, so after revert, the state change to 0 persists? Yes, because state changes are not reverted if the revert happens in the external call. So rewards remain 0 in both.
        assertEq(c.claimedBonus(recipient), false);
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {
        // reenter
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.getFirstWithdrawalBonus.selector, address(this)));
        // ignore success
    }
}

contract RevertReceiver {
    receive() external payable {
        revert("no accept");
    }
}

